import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let ABCDEF be a convex equilateral hexagon with all pairs of opposite sides parallel. The triangle formed by the lines containing AB, CD, and EF has side lengths {side_a}, {side_b}, and {side_c}. Find the common side length of the hexagon.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Construct a triple (a,b,c) that forms a valid triangle and yields integer s = abc/(ab+bc+ca).
# Use the parametrization a = k*m, b = k*n, c = m*n with k = m+n and m*n even.
# Then s = mn/2 (and scaling by g multiplies s by g), while triangle inequality can be enforced.
tries = 0
while tries < 1000:
    m = rng.randint(2, 80)
    n = rng.randint(2, 80)
    if (m*n) % 2 != 0:
        tries += 1
        continue
    k = m + n
    a0 = k * m
    b0 = k * n
    c0 = m * n
    # Triangle inequalities
    if a0 + b0 > c0 and b0 + c0 > a0 and c0 + a0 > b0:
        # scale to increase numeric heft
        g = rng.randint(1, 20)
        a = g * a0
        b = g * b0
        c = g * c0
        # Randomly permute the assignment to avoid a fixed order
        perm = rng.sample([(a, 'side_a'), (b, 'side_b'), (c, 'side_c')], 3)
        out = {}
        for val, key in perm:
            out[key] = val
        return out
    tries += 1
# Fallback (guaranteed valid, integer answer): m=4, n=3, g=10 -> a=280, b=210, c=120
return {'side_a': 280, 'side_b': 210, 'side_c': 120}

    def verifier(assign):
# Validate and compute s = abc/(ab+bc+ca). Enforce triangle inequality and integrality.
# Also ensure nontriviality: distinct sides and answer >= 10 to avoid trivial mental arithmetic.
try:
    a = int(assign.get('side_a'))
    b = int(assign.get('side_b'))
    c = int(assign.get('side_c'))
except Exception:
    # Invalid types
    return False, None  # invalid input types
# Domain checks
if min(a, b, c) <= 0:
    return False, None  # nonpositive side
if not (a + b > c and b + c > a and c + a > b):
    return False, None  # not a valid triangle
if len({a, b, c}) < 2:
    return False, None  # overly trivial (all equal)
# Compute s
num = a * b * c
den = a * b + b * c + c * a
if den == 0:
    return False, None  # undefined
if num % den != 0:
    return False, None  # requires integer s to avoid trivial rounding
s = num // den
# Additional difficulty enforcement: s should not be tiny
if s < 10:
    return False, None  # avoid trivial tiny answers
return True, s


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

